#include <bits/stdc++.h>
using namespace std;

struct Test {
    int R, C;
    long long ch[61][61];
    int cntA[61], cntB[61];
    long long best = LLONG_MAX;
    string str;
    unordered_map<long long, long long> cache;

    void run() {
        R = readInt();
        C = readInt();
        generatePascal();
        long long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R) {
            if (x > y) {
                long long c = ch[v1][R] - ch[v1 - 1][R];
                long long o = ch[v2][R];
                y += c * o;
                v1--;
            } else {
                long long c = ch[v2][R] - ch[v2 - 1][R];
                long long o = ch[v1][R];
                x += c * o;
                v2--;
            }
        }
        best = abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readLine();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str[i] == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str[i] == 'B' ? 1 : 0);
        }
        long long ans = solve(0, 0, R + C, R + C);
        cout << ans << "\n";
    }

    void generatePascal() {
        for (int i = 0; i <= 2 * (R + C); i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i)
                    ch[i][j] = 1;
                else
                    ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j];
            }
        }
    }

    int readInt() {
        string line;
        if (!getline(cin, line))
            return 0;
        return stoi(trim(line));
    }

    string readLine() {
        string line;
        if (!getline(cin, line))
            return "";
        return trim(line);
    }

    string trim(const string& s) {
        size_t start = s.find_first_not_of(" \t\r\n");
        size_t end = s.find_last_not_of(" \t\r\n");
        if (start == string::npos || end == string::npos)
            return "";
        return s.substr(start, end - start + 1);
    }

    long long solve(long long x, long long y, int v1, int v2) {
        long long diff = abs(x - y);
        if (diff - ch[v1][R] * ch[v2][R] > best)
            return 0;
        long long key = x * 10000LL + v1 * 100 + v2;
        auto it = cache.find(key);
        if (it != cache.end())
            return it->second;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return 0;
        }
        long long ans = 0;
        char c = str[v1 + v2 - 1];
        if (c != 'B') {
            long long cur = ch[v1][R] - ch[v1 - 1][R];
            long long other = ch[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long long cur = ch[v2][R] - ch[v2 - 1][R];
            long long other = ch[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        cache[key] = ans;
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Test t;
    t.run();
    return 0;
}

